{-# LANGUAGE PatternSynonyms #-}
{-# LANGUAGE TemplateHaskell #-}
{-# LANGUAGE TypeFamilies #-}

-- | The 'Ghostty' effect and its interpreter (DESIGN.md §4.2, §4.6, §4.7).
--
-- 'Ghostty' is dynamically dispatched, with its operations generated by
-- @effectful-th@'s 'makeEffect'. It has one interpreter: libghostty-vt is
-- headless and deterministic, so the library itself is what tests run
-- against, and a fake would only test the fake. The interpreter owns the
-- thread check and the count of open handles; each operation is one
-- constructor, and later steps add theirs here.
module Ghostty.Effectful.Internal.Effect
  ( -- * The effect
    Ghostty (..),

    -- * Operations
    withTerminal,
    resize,
    reset,
    openTerminals,

    -- * Interpreters
    runGhostty,
    runGhosttyPinnedTo,

    -- * Build identity
    linkedBuild,
  )
where

import Control.Concurrent (ThreadId, myThreadId)
import Effectful (Eff, Effect, IOE, (:>))
import Effectful.Dispatch.Dynamic (LocalEnv, interpret, localSeqUnlift)
import Effectful.Exception (bracket, throwIO)
import Effectful.TH (makeEffect)
import Foreign.Marshal.Alloc (alloca)
import Foreign.Ptr (Ptr, castPtr)
import Foreign.Storable (peek)
import Ghostty.Effectful.Error (CallSite (..), GhosttyError (..), VersionMismatch (..))
import Ghostty.Effectful.Internal.Terminal
  ( CellPixels,
    GridSize,
    Terminal (..),
    TerminalConfig (..),
    freeTerminal,
    newTerminal,
    noCellPixels,
    resetTerminal,
    resizeTerminal,
  )
import Ghostty.FFI.BuildInfo (ghosttyBuildInfo, ghosttyPinnedCommit, pattern GhosttyBuildInfoVersionBuild)
import Ghostty.FFI.Types (GhosttyString, ghosttyStringBytes, pattern GhosttySuccess)

-- | The libghostty-vt binding: the right to make calls, from the thread that
-- ran 'runGhostty', on handles opened in its scope.
data Ghostty :: Effect where
  -- | Open a terminal for the duration of the action, and free it when the
  -- action ends, by return or by exception. The terminal's type variable is
  -- rank-2, so it cannot leave the action (§4.2).
  WithTerminal :: TerminalConfig -> (forall s. Terminal s -> m a) -> Ghostty m a
  -- | Resize the grid and set the cell size. A terminal's primary screen
  -- reflows if wraparound is on; the alternate screen does not.
  Resize :: Terminal s -> GridSize -> CellPixels -> Ghostty m ()
  -- | A full reset (RIS): modes, scrollback, scrolling region and screen
  -- contents, keeping the size.
  Reset :: Terminal s -> Ghostty m ()
  -- | How many terminals are open in this 'runGhostty': each
  -- 'withTerminal' adds one for its duration.
  OpenTerminals :: Ghostty m Int

-- The operations, one per constructor, each documented by its constructor's
-- comment.
makeEffect ''Ghostty

-- | Run the effect against the linked libghostty-vt, which must be the pinned
-- build (§3.4): otherwise nothing runs, and the result is the mismatch. Every
-- operation must then come from this thread, or it throws 'WrongThread'
-- (§4.6).
runGhostty :: (IOE :> es) => Eff (Ghostty : es) a -> Eff es (Either VersionMismatch a)
runGhostty = runGhosttyPinnedTo (decodeUtf8 ghosttyPinnedCommit)

-- | 'runGhostty' with another pin in place of @GHOSTTY_COMMIT@, which is how
-- the mismatch is tested.
runGhosttyPinnedTo :: (IOE :> es) => Text -> Eff (Ghostty : es) a -> Eff es (Either VersionMismatch a)
runGhosttyPinnedTo pin act = do
  linked <- liftIO linkedBuild
  if linked /= Just pin
    then pure (Left VersionMismatch {pinned = pin, linked})
    else do
      owner <- liftIO myThreadId
      open <- newIORef (0 :: Int)
      Right <$> interpret (handler owner open) act

handler :: (IOE :> es) => ThreadId -> IORef Int -> LocalEnv localEs -> Ghostty (Eff localEs) a -> Eff es a
handler owner open env = \case
  WithTerminal cfg k -> do
    onOwner "withTerminal"
    localSeqUnlift env $ \unlift ->
      bracket
        (liftIO (newTerminal cfg) <* modifyIORef' open (+ 1))
        (\h -> liftIO (freeTerminal h) <* modifyIORef' open (subtract 1))
        ( \h -> do
            when (cfg.cellPixels /= noCellPixels) $
              liftIO (resizeTerminal h cfg.size cfg.cellPixels)
            unlift (k (Terminal h))
        )
  Resize (Terminal h) g px -> do
    onOwner "resize"
    liftIO (resizeTerminal h g px)
  Reset (Terminal h) -> do
    onOwner "reset"
    liftIO (resetTerminal h)
  OpenTerminals -> do
    onOwner "openTerminals"
    readIORef open
  where
    onOwner :: (IOE :> es') => Text -> Eff es' ()
    onOwner op = do
      me <- liftIO myThreadId
      when (me /= owner) $ throwIO (WrongThread (CallSite op))

-- | The linked library's build metadata (@VERSION_BUILD@), which
-- @scripts/build-libghostty.sh@ stamps with the commit it built; 'Nothing' if
-- the library would not say. Build info is a constant of the library, so this
-- needs no owner.
linkedBuild :: IO (Maybe Text)
linkedBuild = alloca $ \(p :: Ptr GhosttyString) -> do
  r <- ghosttyBuildInfo GhosttyBuildInfoVersionBuild (castPtr p)
  if r /= GhosttySuccess
    then pure Nothing
    else Just . decodeUtf8 <$> (ghosttyStringBytes =<< peek p)
